def _fs_get(url, **kwargs):
    """GET request to FatSecret API."""
    kwargs.setdefault("timeout", 10)
    return http_requests_lib.get(url, **kwargs)


def _fs_post(url, **kwargs):
    """POST request to FatSecret API."""
    kwargs.setdefault("timeout", 10)
    return http_requests_lib.post(url, **kwargs)


_fs_token_lock = threading.Lock()


_fs_token_cache = {"token": None, "expires_at": 0}


def _get_fatsecret_token() -> str:
    # Kilit, getirme dahil tüm kritik bölümü kapsar: soğuk önbellekte eşzamanlı
    # çağrılar her biri ayrı token alıp thundering-herd yapmasın; ilk çağrı
    # önbelleği doldurur, bekleyenler tekrar kontrolde önbelleği bulur (F13).
    # Token getirme seyrek olduğundan kilidi ağ çağrısı boyunca tutmak sorun değil.
    with _fs_token_lock:
        if _fs_token_cache["token"] and time.time() < _fs_token_cache["expires_at"] - 60:
            return _fs_token_cache["token"]
        client_id = os.environ.get("FATSECRET_CLIENT_ID", "")
        client_secret = os.environ.get("FATSECRET_CLIENT_SECRET", "")
        if not client_id or not client_secret:
            raise RuntimeError("FATSECRET_CLIENT_ID / FATSECRET_CLIENT_SECRET not set")
        resp = _fs_post(
            FATSECRET_TOKEN_URL,
            data={"grant_type": "client_credentials", "scope": "basic"},
            auth=(client_id, client_secret),
            timeout=10,
        )
        resp.raise_for_status()
        try:
            data = resp.json()
        except ValueError as e:
            # Hata sayfası/HTML döndüyse json() patlar; önbelleği bozma, anlamlı hata ver.
            raise RuntimeError(f"FatSecret token yanıtı JSON değil: {e}") from e
        if not isinstance(data, dict) or data.get("error") or not data.get("access_token"):
            # OAuth hata yükü ({"error": "..."}) veya eksik access_token: data["access_token"]
            # ham KeyError yerine açık hata at, önbelleği ASLA boş/yanlış token'la doldurma.
            err = data.get("error") if isinstance(data, dict) else data
            raise RuntimeError(f"FatSecret token alınamadı: {err}")
        _fs_token_cache["token"] = data["access_token"]
        _fs_token_cache["expires_at"] = time.time() + data.get("expires_in", 86400)
        return data["access_token"]


def _parse_fatsecret_desc(desc: str) -> dict | None:
    if not desc:
        return None
    parts = {}
    try:
        segments = desc.split(" - ", 1)
        if len(segments) == 2:
            parts["serving"] = segments[0].strip()
            macros = segments[1]
        else:
            macros = desc
        _num_pat = re.compile(r"(\d+(?:[.,]\d+)?)")
        for item in macros.split("|"):
            item = item.strip()
            if ":" not in item:
                continue
            key, val = item.split(":", 1)
            key = key.strip().lower()
            num_match = _num_pat.search(val)
            if num_match:
                num_str = num_match.group(1).replace(",", ".")
                try:
                    parts[key] = float(num_str)
                except ValueError:
                    parts[key] = 0.0
    except Exception:
        return None
    return parts if len(parts) > 1 else None


_BULK_SERVING_GRAMS = 500.0


def _is_100g_serving(r):
    """unit ne olursa olsun ~100'lük (gerçek veya türetilmiş) baz porsiyon mu?"""
    return abs(r.get("metric_serving_amount", 0) - 100) < 0.5


def _normalize_servings(results):
    """FatSecret servings listesini güvenilir 100g bazına oturt ve devasa
    'tüm tarif/tencere' porsiyonlarını işaretle.

    - Gerçek bir 100g (amount≈100) satırı varsa onu baz alır; yoksa makul
      (≤500g) bir 'donor' porsiyondan 1g başına oranlayıp 100g türetir
      (ölçekleme lineer olduğundan değerler tutarlı kalır).
    - Her serving'e is_bulk bayrağı ekler (metric_serving_amount > 500g).
    - Sıralar: önce makul tek porsiyonlar, sonra 100 g bazı, en sonda is_bulk
      satırlar — böylece UI'daki ilk/varsayılan seçim asla devasa tarif olmaz.
    """
    if not results:
        return results

    # Devasa "tüm tarif" porsiyonlarını işaretle.
    for r in results:
        r["is_bulk"] = r.get("metric_serving_amount", 0) > _BULK_SERVING_GRAMS

    # 100g bazı yoksa sentetik bir tane türet — donor olarak makul (bulk
    # olmayan) en büyük porsiyonu seç; hiç makul porsiyon yoksa son çare en büyüğü.
    if not any(_is_100g_serving(r) for r in results):
        sane = [r for r in results if r["metric_serving_amount"] > 0 and not r["is_bulk"]]
        pool = sane or [r for r in results if r["metric_serving_amount"] > 0]
        donor = max(pool, key=lambda r: r["metric_serving_amount"], default=None)
        if donor:
            scale = 100.0 / donor["metric_serving_amount"]
            results.append({
                "serving_id": "100g_calc",
                "serving_description": "100 g",
                "metric_serving_amount": 100.0,
                "metric_serving_unit": "g",
                "calories": round(donor["calories"] * scale, 1),
                "protein": round(donor["protein"] * scale, 1),
                "carbs": round(donor["carbs"] * scale, 1),
                "fat": round(donor["fat"] * scale, 1),
                "is_bulk": False,
            })
        else:
            current_app.logger.warning("_normalize_servings: cannot derive 100g — all servings lack metric_serving_amount")

    # Sırala: makul tek porsiyonlar (0,0) → 100 g bazı (0,1) → bulk (1,*) en sonda.
    def _sort_key(r):
        return (1 if r.get("is_bulk") else 0,
                1 if _is_100g_serving(r) else 0,
                r.get("metric_serving_amount", 0))
    results.sort(key=_sort_key)
    return results


def _food_get_servings(food_id):
    try:
        token = _get_fatsecret_token()
        current_app.logger.info("_food_get_servings: got token for food_id=%s", food_id)
    except Exception as e:
        current_app.logger.error("_food_get_servings: token failed: %s", e)
        return None

    servings_raw = None
    for method in ("food.get.v4", "food.get.v2", "food.get"):
        try:
            resp = _fs_get(FATSECRET_API_URL, params={
                "method": method,
                "food_id": food_id,
                "format": "json",
            }, headers={"Authorization": f"Bearer {token}"}, timeout=5)
            data = resp.json()
            current_app.logger.info("_food_get_servings %s status=%s keys=%s",
                            method, resp.status_code, list(data.keys())[:5])
        except Exception as e:
            current_app.logger.warning("_food_get_servings %s failed: %s", method, e)
            continue

        if "error" in data:
            current_app.logger.warning("_food_get_servings %s error: %s", method, data["error"])
            continue

        try:
            servings_raw = data["food"]["servings"]["serving"]
            if isinstance(servings_raw, dict):
                servings_raw = [servings_raw]
            current_app.logger.info("_food_get_servings %s OK: %d servings", method, len(servings_raw))
            break
        except (KeyError, TypeError):
            current_app.logger.warning("_food_get_servings %s: no servings in response keys=%s",
                               method, list(data.get("food", {}).keys()) if "food" in data else list(data.keys()))
            continue

    if not servings_raw:
        return None

    results = []
    for s in servings_raw:
        # Anahtar eslemesi (protein/carbohydrate/fat) ve metrik-agirlik tahmini tek
        # noktada, test edilebilir saf fonksiyonda yapilir (nutrition_pipeline).
        item = nutrition_pipeline.parse_fatsecret_serving(s)
        if float(s.get("metric_serving_amount") or 0) == 0:
            if item["metric_serving_amount"] > 0:
                current_app.logger.info("_food_get_servings food_id=%s: '%s' metrik agirligi yok -> matris tahmini %.0fg",
                                food_id, item["serving_description"] or "?", item["metric_serving_amount"])
            else:
                current_app.logger.warning("_food_get_servings food_id=%s: serving '%s' has no metric_serving_amount",
                                   food_id, item["serving_description"] or "?")
        results.append(item)

    if not results:
        return None

    # Deterministik saglik/biyoloji kontrolleri: imkansiz girdileri (P+C+F > agirlik,
    # 100g basina >900 kcal) DB'ye/skora gecmeden once ele.
    results = nutrition_pipeline.sanitize_servings(results)
    if not results:
        current_app.logger.warning("_food_get_servings food_id=%s: tum porsiyonlar saglik kontrolunden geri dondu", food_id)
        return None

    # 100g bazına normalize et + devasa "tüm tarif" porsiyonlarını işaretle/en sona it.
    return _normalize_servings(results)


def _food_search_fatsecret(q):
    """Try FatSecret API. Returns list of results or None on failure."""
    try:
        token = _get_fatsecret_token()
    except Exception:
        return None

    try:
        resp = _fs_get(FATSECRET_API_URL, params={
            "method": "foods.search",
            "search_expression": q,
            "format": "json",
            "max_results": 8,
        }, headers={"Authorization": f"Bearer {token}"}, timeout=5)
        data = resp.json()
    except Exception:
        return None

    if "error" in data:
        return None

    foods = data.get("foods", {}).get("food", [])
    if isinstance(foods, dict):
        foods = [foods]
    if not foods:
        return None

    results = []
    for f in foods:
        desc = f.get("food_description", "")
        parsed = _parse_fatsecret_desc(desc)
        if not parsed:
            continue
        cal_val = parsed.get("calories") or parsed.get("cal") or parsed.get("energy") or 0
        if not cal_val:
            continue
        macros = {
            "calories": float(cal_val),
            "protein": float(parsed.get("protein", 0)),
            "carbs": float(parsed.get("carbs", parsed.get("carbohydrate", parsed.get("carb", 0)))),
            "fat": float(parsed.get("fat", parsed.get("total fat", 0))),
        }
        serving_text = parsed.get("serving", "")
        is_serving = _is_per_serving(serving_text)

        # per_100g, macros'tan AYRI bir kopya olmali: ayni nesne hem sonuca hem
        # _macro_cache'e konursa, ileride biri yerinde (in-place) degistirdiginde
        # onbellek ve diger besinler bozulur (todos.txt §1 — referans paylasimi).
        per_100g = dict(macros)
        if is_serving:
            est = _estimate_serving_weights_llm([f.get("food_name", q)])
            weight_g = est.get(f.get("food_name", q), 150.0)
            if weight_g and weight_g > 0:
                scale = 100.0 / weight_g
                per_100g = {
                    "calories": round(macros["calories"] * scale, 1),
                    "protein": round(macros["protein"] * scale, 1),
                    "carbs": round(macros["carbs"] * scale, 1),
                    "fat": round(macros["fat"] * scale, 1),
                }

        # Deterministik saglik kontrolu: imkansiz girdiyi (100g basina >900 kcal,
        # makro-agirlik ihlali) arama sonuclarindan ele. LLM kullanilmaz.
        valid_100g, _flags, _reasons = nutrition_pipeline.check_serving({
            "metric_serving_amount": 100.0,
            "calories": per_100g["calories"],
            "protein": per_100g["protein"],
            "carbs": per_100g["carbs"],
            "fat": per_100g["fat"],
        })
        if not valid_100g:
            continue

        name = f.get("food_name", "")
        fid = f.get("food_id", "")
        _cache_macros({name: per_100g}, basis="per_100g")
        if fid:
            _cache_food_id(name, fid)
        results.append({
            "name": name,
            "brand": f.get("brand_name", ""),
            "food_id": fid,
            "serving": serving_text,
            "is_per_serving": is_serving,
            "macros": macros,
            "per_100g": per_100g,
            "food_type": f.get("food_type", ""),
        })

    # Dogrulama filtresi: 'Generic' girdileri one al (kararli siralama FatSecret
    # alaka sirasini grup icinde korur).
    results.sort(key=lambda r: 0 if str(r.get("food_type", "")).strip().lower() == "generic" else 1)
    return results if results else None


