def _food_search_static(q):
    """Last-resort fallback: match against built-in food database."""
    q_lower = q.lower().strip()
    matches = []
    for key, foods in _STATIC_FOODS.items():
        if q_lower in key or key in q_lower:
            matches.extend(foods)
    if not matches:
        return []
    results = []
    for item in matches[:8]:
        per_100g = {
            "calories": item["calories"], "protein": item["protein"],
            "carbs": item["carbs"], "fat": item["fat"],
        }
        _cache_macros({item["name"]: per_100g}, basis="per_100g")
        results.append({
            "name": item["name"], "brand": "", "food_id": "",
            "serving": "Per 100g", "is_per_serving": False,
            "macros": per_100g, "per_100g": per_100g
        })
    return results


def _is_per_serving(serving_text):
    if not serving_text:
        return False
    s = serving_text.lower()
    per_100_patterns = ("per 100g", "per 100 g", "100g başına", "100 gram")
    if any(p in s for p in per_100_patterns):
        return False
    serving_patterns = ("per 1 serving", "per serving", "1 serving", "1 portion",
                        "1 plate", "1 porsiyon", "1 tabak", "per 1 cup", "per 1 bowl")
    return any(p in s for p in serving_patterns)


def _fs_search_foods(query, token):
    """Tek bir FatSecret foods.search çağrısı → ham 'food' dict listesi (veya []).
    Ağ/format hatasında sessizce [] döner (çağıran karar verir)."""
    try:
        resp = _fs_get(FATSECRET_API_URL, params={
            "method": "foods.search",
            "search_expression": query,
            "format": "json",
            "max_results": 5,
        }, headers={"Authorization": f"Bearer {token}"}, timeout=5)
        data = resp.json()
        if "error" in data:
            return []
        foods = data.get("foods", {}).get("food", [])
        if isinstance(foods, dict):
            foods = [foods]
        return foods or []
    except Exception as e:
        current_app.logger.warning(f"[MACRO ENGINE] FatSecret search failed for '{query}': {type(e).__name__}: {e}")
        return []


def _fs_relevant_candidates(name, english, token, category=None):
    """FatSecret aday besinlerini KATI alaka kapısından geçir + en spesifik eşleşmeyi
    öne al — menü makro hattı için ham 'food' dict'leri döndürür.

    FatSecret veritabanı ağırlıklı İngilizce/ABD ve eşleyemediği Türkçe sorgulara iki
    tür hata yapar:
      (a) Tamamen ilgisiz jenerik ('Çay' → yüksek-proteinli ürün) — token örtüşmesi
          olmadığı için kapı eler.
      (b) AİLE-ÇÖKMESİ: bilmediği niteleyiciyi yok sayıp tüm aileye aynı jenerik
          kaydı verir ('Tavuk/Mantar/Vejetaryen Burger' → hepsi 'Burger' → özdeş,
          yanlış makro; 0 g karblı köfte). `_is_specific_match` çok-kelimeli sorguda
          ≥2 token örtüşmesi istediği için bu jenerikleri de eler.

    `category` verilirse VE başlık bir yemek-türü dayatıyorsa (Pizzalar→pizza,
    Salatalar→salad) aday adının da o türden olması istenir: 'Pizzalar' kategorisindeki
    'Margarita' ham aramada KOKTEYL 'Margarita'ya birebir eşleşir (tür kapısı sorguda
    yok çünkü 'margarita' bir tür adı değil) — kategori kapısı pizza token'ı olmayan
    bu kaydı eler; gerçek 'Margherita Pizza' (ham veya İngilizce pass'te) kazanır.

    Strateji `_coach_search_food` ile aynı: 1) ham (Türkçe) sorgu → kapı; 2) boşsa
    önceden hesaplanmış İngilizce terim → kapı. Geçen adaylar, sorgunun EN ÇOK
    token'ını karşılayana göre azalan sıralanır (kararlı) → çağıran ilk/varsayılan
    porsiyonu seçtiğinde en spesifik kayıt kazanır. Hiç spesifik aday yoksa [] döner
    → öğe LLM tahminine bırakılır (niteleyiciye göre ayırt eden gerçekçi porsiyon)."""
    cat_types = _dish_types(category) if category else set()

    def _filter_sorted(query, foods):
        relevant = []
        for f in foods:
            fname = f.get("food_name", "")
            if not _is_specific_match(query, fname):
                continue
            # Kategori bir yemek-türü dayatıyorsa aday da o türden olmalı.
            if cat_types and not (cat_types & _dish_types(fname)):
                continue
            relevant.append(f)
        # Kararlı sıralama: en çok token örtüşeni (en spesifik) öne al; FatSecret'in
        # grup-içi alaka sırasını eşit-skorlular arasında korur.
        relevant.sort(key=lambda f: _token_match_count(query, f.get("food_name", "")), reverse=True)
        return relevant

    relevant = _filter_sorted(name, _fs_search_foods(name, token))
    if relevant:
        return relevant
    if english and english.lower() != name.lower():
        relevant = _filter_sorted(english, _fs_search_foods(english, token))
        if relevant:
            return relevant
    return []


def _lookup_macros_fatsecret(items, token, category_map=None):
    per_serving = {}
    per_100g = {}
    category_map = category_map or {}
    # Tüm öğe adlarını TEK çağrıda İngilizce'ye çevir (ham Türkçe sorgular FatSecret'ta
    # nadiren eşleştiği için alaka-kapısı sonrası yedek arama terimi). Menü kategorisi
    # ayırt edici bağlam olarak iletilir ('Margarita'@Pizzalar → 'margherita pizza').
    # Hata → {} → yalnızca ham sorgu + kapı (yine de eski körlemesine davranıştan iyi).
    english_map = _normalize_food_queries_en(items, category_map)
    for name in items:
        try:
            foods = _fs_relevant_candidates(name, english_map.get(name, ""), token, category_map.get(name))
            if not foods:
                current_app.logger.info(f"[MACRO ENGINE] FatSecret: '{name}' için alakalı eşleşme yok → LLM yedeği")
                continue

            found_serving = False
            baseline_100g = None
            converted_baseline = None

            for food in foods:
                desc_raw = food.get("food_description", "")
                parsed = _parse_fatsecret_desc(desc_raw)
                if not parsed:
                    continue
                cal_val = parsed.get("calories") or parsed.get("cal") or parsed.get("energy") or 0
                if not cal_val:
                    continue
                macros = {
                    "calories": float(cal_val),
                    "protein": float(parsed.get("protein", 0)),
                    "carbs": float(parsed.get("carbs", parsed.get("carbohydrate", parsed.get("carb", 0)))),
                    "fat": float(parsed.get("fat", parsed.get("total fat", 0))),
                }
                serving_text = parsed.get("serving", "")
                is_serv = _is_per_serving(serving_text)

                # Saf yag/sivi-yag BILESENINI ele: FatSecret 'zeytin/olive' aramasina
                # 'Olive Oil' (saf yag) donduruyor; 'Zeytin Tabagi'na eslesince
                # porsiyon agirligiyla olceklenip 1300+ kcal / 150g yag uretiyordu.
                # Bu bir yemek degil bilesen → atla; gercek 'Olives' adayi veya LLM
                # tahmini kazansin. (Yalnizca menu hatti; kocta yag loglamak serbest.)
                if nutrition_pipeline.is_pure_fat_ingredient(macros):
                    current_app.logger.info(f"[MACRO ENGINE] FatSecret saf-yag bileseni atlandi '{name}': {food.get('food_name','?')} {macros}")
                    continue

                # Deterministik saglik kontrolu: imkansiz girdiyi (kalori-makro enerji
                # ihlali, mutlak porsiyon tavanlari, 100g basina >900 kcal) kaynakta
                # ele. 100g bazinda yogunluk kontrolu icin amount=100 ver. LLM'siz.
                valid_fs, _f, _r = nutrition_pipeline.check_serving({
                    "metric_serving_amount": 0 if is_serv else 100.0,
                    "calories": macros["calories"],
                    "protein": macros["protein"],
                    "carbs": macros["carbs"],
                    "fat": macros["fat"],
                })
                if not valid_fs:
                    current_app.logger.info(f"[MACRO ENGINE] FatSecret implausible entry skipped for '{name}': {macros} reasons={_r}")
                    continue

                if is_serv:
                    # Porsiyon-makulluk kapisi (docs/menu-porsiyon-eslesme-hatasi.md):
                    # FatSecret 'serving' cogu zaman kucuk ABD referans miktaridir
                    # (tek kofte, 1/2 cup) → tam tabak sanilirsa 2-3x eksik kalori.
                    # Tur-bazli kalori bandi + asgari-gram kontrolu KIMLIGI degil
                    # MIKTARI denetler; karar saf fonksiyonda (gate_per_serving).
                    dish_type = _primary_dish_type(name, category_map.get(name))
                    est_g = nutrition_pipeline.estimate_serving_grams(serving_text)
                    status, conv = nutrition_pipeline.gate_per_serving(dish_type, macros, est_g)
                    if status == "accept":
                        # Kimlik-hatasi kapisi: porsiyon-makulluk (miktar) gecse bile
                        # kayit yanlis YEMEGE carpmis olabilir → ekmek bazli yemekte
                        # 0 karb (ekmeksiz patty) ya da protein-adli yemekte ~0 protein
                        # (sos eslesmesi). Reddet → oge LLM yedegine duser (gercekci).
                        if (nutrition_pipeline.is_breadbased_zero_carb(macros, dish_type)
                                or nutrition_pipeline.is_protein_dish_low_protein(name, macros, dish_type)):
                            current_app.logger.info(f"[MACRO ENGINE] FatSecret kimlik-hatasi reddedildi '{name}' ({dish_type}): {macros}")
                            continue
                        per_serving[name] = macros
                        found_serving = True
                        current_app.logger.info(f"[MACRO ENGINE] FatSecret per-serving match: '{name}' → Cal={macros['calories']}, P={macros['protein']}, C={macros['carbs']}, F={macros['fat']}")
                        break
                    if status == "skip":
                        current_app.logger.info(f"[MACRO ENGINE] FatSecret per-serving band-USTU atlandi '{name}' ({dish_type}): {macros}")
                        continue
                    # "convert": tam tabak degil → 100g-esdegeri olarak sakla; dongu
                    # surer ki band-ICI daha sonraki bir per-serving aday kazanabilsin.
                    if converted_baseline is None:
                        converted_baseline = conv
                        current_app.logger.info(f"[MACRO ENGINE] FatSecret per-serving 100g-esdegerine cevrildi '{name}' ({dish_type}, est_g={est_g}): {macros} → {conv}")
                    continue
                if baseline_100g is None:
                    baseline_100g = macros

            if not found_serving:
                # Gercek 100g yogunlugu, per-serving'den cevrilmis esdegere tercih edilir.
                chosen = baseline_100g or converted_baseline
                if chosen:
                    per_100g[name] = chosen
                    current_app.logger.info(f"[MACRO ENGINE] FatSecret per-100g baseline: '{name}' → Cal={chosen['calories']}/100g")

        except Exception as e:
            current_app.logger.warning(f"[MACRO ENGINE] FatSecret lookup failed for '{name}': {type(e).__name__}: {e}")
            continue
    current_app.logger.info(f"[MACRO ENGINE] FatSecret totals: {len(per_serving)} per-serving, {len(per_100g)} per-100g, {len(items) - len(per_serving) - len(per_100g)} missed")
    return per_serving, per_100g
